import { Component, inject, signal, computed, resource, effect } from '@angular/core';
import { Router } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { SesionService } from '../../../shared/services/sesion.service';
import { AuthService } from '../../../services/auth.service';
import { PaginatorComponent } from '../../../shared/components/paginator/paginator.component';
import { SemaforoData } from '../../../shared/models/solicitud.model';
import { semaforoBadgeClass } from '../../../shared/models/solicitud-status.util';

interface SesionMiembro {
  id: number;
  name: string;
  nivelGobierno: string;
  vistoBueno?: { decision: string };
}

interface SesionListItem {
  id: number;
  comiteId: number;
  solicitudFolio: string;
  fecha: string;
  hora: string;
  observaciones: string | null;
  status: 'programada' | 'en_curso' | 'cerrada';
  miembros: SesionMiembro[];
  recomendacion?: { aceptados: number; noAceptados: number; total: number; cerrada: boolean };
  semaforo?: SemaforoData | null;
}

@Component({
  selector: 'app-sesiones-list',
  imports: [PaginatorComponent],
  templateUrl: './sesiones-list.component.html',
})
export class SesionesListComponent {
  private readonly router = inject(Router);
  private readonly sesionService = inject(SesionService);
  private readonly authService = inject(AuthService);

  readonly semaforoBadgeClass = semaforoBadgeClass;

  readonly activeTab = signal<'pendientes' | 'todas'>('pendientes');
  readonly page = signal(1);
  readonly perPage = signal(15);

  readonly currentUserId = computed(() => this.authService.currentUser()?.id);

  readonly pendientesResource = resource({
    loader: () => firstValueFrom(this.sesionService.getMisPendientes()),
  });

  readonly todasResource = resource({
    params: () => ({ page: this.page(), perPage: this.perPage() }),
    loader: () => firstValueFrom(this.sesionService.getSesiones()),
  });

  readonly pendientes = computed(() => {
    return (this.pendientesResource.value() ?? []) as unknown as SesionListItem[];
  });

  readonly todasData = computed(() => {
    return this.todasResource.value() ?? null;
  });

  readonly todas = computed(() => (this.todasData()?.data ?? []) as unknown as SesionListItem[]);

  readonly paginationMeta = computed(() => {
    const d = this.todasData();
    return d
      ? { currentPage: d.current_page, lastPage: d.last_page, total: d.total, perPage: d.per_page }
      : { currentPage: 1, lastPage: 1, total: 0, perPage: 15 };
  });

  readonly isLoading = computed(() =>
    this.activeTab() === 'pendientes'
      ? this.pendientesResource.isLoading()
      : this.todasResource.isLoading(),
  );

  readonly error = computed(() => {
    const err = this.activeTab() === 'pendientes'
      ? this.pendientesResource.error()
      : this.todasResource.error();
    return err ? (err as Error).message || 'Error cargando sesiones' : null;
  });

  constructor() {
    effect(() => {
      if (this.activeTab() === 'todas') {
        this.todasResource.reload();
      }
    });
  }

  switchTab(tab: 'pendientes' | 'todas'): void {
    this.activeTab.set(tab);
    if (tab === 'todas') {
      this.page.set(1);
    }
  }

  onPageChange(page: number): void {
    this.page.set(page);
  }

  onPageSizeChange(size: number): void {
    this.perPage.set(size);
    this.page.set(1);
  }

  goToSesion(id: number): void {
    this.router.navigate(['/ejecutivos/sesiones', id]);
  }

  hasPendingVote(sesion: SesionListItem): boolean {
    const userId = this.currentUserId();
    if (!userId) return false;
    return sesion.miembros.some(m => m.id === userId && !m.vistoBueno);
  }

  statusBadgeClass(status: string): string {
    switch (status) {
      case 'programada': return 'bg-secondary';
      case 'en_curso': return 'bg-info text-dark';
      case 'cerrada': return 'bg-success';
      default: return 'bg-secondary';
    }
  }

  statusLabel(status: string): string {
    switch (status) {
      case 'programada': return 'Programada';
      case 'en_curso': return 'En curso';
      case 'cerrada': return 'Cerrada';
      default: return status;
    }
  }

  recomendacionText(rec: SesionListItem['recomendacion']): string | null {
    if (!rec) return null;
    return `Aceptado ${rec.aceptados}/${rec.total}`;
  }
}
